object Counter {
  sealed trait Msg
  final case class Add(n: Int) extends Msg
  final case class Get(replyTo: ActorRef[Int]) extends Msg

  def apply(count: Int = 0): Behavior[Msg] = Behaviors.receive { (ctx, msg) =>
    msg match {
      case Add(n)       => Counter(count + n)         // next behavior carries new state
      case Get(replyTo) => replyTo ! count; Behaviors.same
    }
  }
}

val counter = system.spawn(Counter(), "counter")      // ActorRef is the address
counter ! Counter.Add(1)
